import { v4 as uuidv4 } from "uuid";

const Menu = () => {
    const list_menu = [
        {link:"https://github.com/xobazjr",title:"01 GutHub"},
        {link:"https://www.facebook.com/XobazJr/",title:"02 Facebook"},
        {link:"https://www.instagram.com/xobazjr/",title:"03 Instagram"},
        {link:"https://www.tiktok.com/@xobazjr",title:"04 TikTok"},
        {link:"https://www.youtube.com/@XobazJr",title:"05 YouTube"}
    ]
    return (
        <section class="Menu text-body">
            <ul>
                {list_menu.map((element)=>{
                    return <li><a href={element.link} target="_blank" rel="noopener noreferrer" key= {uuidv4()}>{element.title}</a></li>
                })}
            </ul>
        </section>
    );
}

export default Menu;
